mapper.update:
UPDATE coordinator_agent_run SET stage = #{stage}, status = 'RUNNING',
updated_at = CURRENT_TIMESTAMP
WHERE business_id = #{id} AND session_id = #{sessionId}

UPDATE coordinator_agent_run SET last_sequence = #{sequence}, status = #{status},
updated_at = CURRENT_TIMESTAMP
WHERE business_id = #{id} AND last_sequence < #{sequence}

UPDATE coordinator_agent_run SET last_sequence = #{sequence},
status = 'SUCCEEDED', output_json = #{output}, updated_at = CURRENT_TIMESTAMP
WHERE business_id = #{id}

UPDATE coordinator_agent_run SET stage = 'REPAIR',
status = 'PENDING', invalid_output = #{invalidOutput},
output_json = NULL, updated_at = CURRENT_TIMESTAMP WHERE business_id = #{id}
